1: /* Molt — watercolor bug fable
2:    Palette: paper, moss, pond, ink, rust, marigold */
3: 
4: :root {
5:   --paper: #f4ecd8;
6:   --paper-2: #efe4ca;
7:   --paper-light: #fbf5e6;
8:   --ink: #333827;
9:   --ink-soft: #5c6147;
10:   --ink-faint: #7c8066;
11:   --moss: #6f8155;
12:   --moss-deep: #49593a;
13:   --water: #4f8c86;
14:   --water-deep: #376c69;
15:   --berry: #a0504a;
16:   --berry-deep: #7c3a36;
17:   --gold: #b8893f;
18:   --line: rgba(58, 62, 45, .26);
19:   --line-soft: rgba(58, 62, 45, .14);
20:   --panel: rgba(250, 244, 229, .78);
21:   --shadow: 0 18px 50px rgba(53, 58, 38, .16);
22:   --serif: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Palatino, "DejaVu Serif", Georgia, serif;
23:   --sans: "Lato", "Avenir Next", "Segoe UI", "DejaVu Sans", sans-serif;
24:   --safe-b: env(safe-area-inset-bottom, 0px);
25:   --safe-l: env(safe-area-inset-left, 0px);
26:   --safe-r: env(safe-area-inset-right, 0px);
27:   --safe-t: env(safe-area-inset-top, 0px);
28: }
29: 
30: * { box-sizing: border-box; }
31: 
32: html, body {
33:   margin: 0;
34:   height: 100%;
35:   overflow: hidden;
36:   overscroll-behavior: none;
37:   background: var(--paper);
