634: .stick-knob {
635:   position: absolute;
636:   left: 50%;
637:   top: 50%;
638:   width: 42px;
639:   height: 42px;
640:   margin: -21px 0 0 -21px;
641:   border-radius: 50%;
642:   background: radial-gradient(circle at 35% 30%, rgba(255, 252, 242, .95), rgba(214, 210, 177, .8));
643:   border: 1px solid rgba(70, 76, 52, .3);
644:   box-shadow: 0 5px 14px rgba(55, 60, 38, .16);
645:   transition: transform .08s linear;
