154: function moveStick(e) {
155:   const dx = e.clientX - stick.cx;
156:   const dy = e.clientY - stick.cy;
157:   const max = 42;
158:   const len = Math.hypot(dx, dy);
159:   const k = len > max ? max / len : 1;
160:   const ox = dx * k, oy = dy * k;
161:   stick.x = ox / max;
162:   stick.y = oy / max;
163:   ui.stickKnob.style.transform = `translate(${ox}px, ${oy}px)`;
164: }
