193: function inputVector() {
194:   let ix = 0, iy = 0, mag = 1;
195:   if (keys.has('KeyA') || keys.has('ArrowLeft')) ix -= 1;
196:   if (keys.has('KeyD') || keys.has('ArrowRight')) ix += 1;
197:   if (keys.has('KeyW') || keys.has('ArrowUp')) iy -= 1;
198:   if (keys.has('KeyS') || keys.has('ArrowDown')) iy += 1;
199:   if (ix || iy) {
200:     const l = Math.hypot(ix, iy);
201:     return { x: ix / l, y: iy / l, mag: 1 };
202:   }
203:   if (stick.active && (stick.x || stick.y)) {
204:     const l = Math.hypot(stick.x, stick.y);
205:     if (l > 0.08) return { x: stick.x / Math.max(1, l), y: stick.y / Math.max(1, l), mag: Math.min(1, l) };
206:   }
207:   if (pointer.active && !isTouch) {
208:     const wx = game.cam.x + (pointer.x - view.w / 2) / game.cam.zoom;
209:     const wy = game.cam.y + (pointer.y - view.h / 2) / game.cam.zoom;
210:     const dx = wx - game.player.x, dy = wy - game.player.y;
211:     const d = Math.hypot(dx, dy);
212:     if (d > 14) return { x: dx / d, y: dy / d, mag: clamp(d / 150, 0.25, 1) };
213:   }
214:   return { x: 0, y: 0, mag: 0 };
215: }
