383: function initWorld(save) {
384:   game.state = 'loading';
385:   game.player = createPlayerData(save ? save.stage : 0);
386:   game.stage = game.player.stage;
387:   game.biomass = save ? save.biomass : 0;
388:   game.eaten = save ? save.eaten : 0;
389:   game.playTime = save ? save.time : 0;
390:   game.bossDead = save ? !!save.bossDead : false;
391:   game.bossEngaged = false;
392:   game.time = 0;
393:   game.shake = 0; game.hurtFlash = 0; game.slowmo = 0; game.winTimer = 0;
394:   game.drinking = false; game.blocked = false; game.toughCd = 0; game.flowerCd = 0;
395:   game.saveAt = 0; game.toastTimer = 0; game.introTimer = 0; game.bossIntro = false;
396:   setStage(game.stage, true);
397: 
398:   const p = game.player;
399:   const wasDead = !!save && save.hp <= 0;
400:   if (save) {
401:     if (wasDead) {
402:       const respawnZone = ZONES[Math.min(3, game.stage)];
403:       p.x = respawnZone.x0 + 200;
404:       p.y = pathY(p.x);
405:     } else {
406:       p.x = clamp(save.x || 500, 60, WORLD_W - 60);
407:       p.y = clamp(save.y || pathY(p.x), 60, WORLD_H - 60);
408:     }
409:     p.hp = wasDead ? p.maxHp : clamp(save.hp ?? p.maxHp, 1, p.maxHp);
410:     p.hunger = clamp(save.hunger ?? 70, 0, 100);
411:     p.thirst = clamp(save.thirst ?? 62, 0, 100);
412:     if (wasDead) {
413:       p.hunger = Math.max(58, p.hunger);
414:       p.thirst = Math.max(58, p.thirst);
415:       p.hurtT = 1.8;
416:       p.attackCd = 0.4;
417:     }
418:   } else {
419:     p.x = 500;
420:     p.y = pathY(500);
421:   }
422:   // never restore beyond an unopened gate
423:   for (const b of BARRIERS) {
424:     if (game.stage < b.require && p.x > b.x - 50) p.x = b.x - 50;
425:   }
426:   p.y = clamp(p.y, 70, WORLD_H - 70);
427:   game.zoneIndex = zoneIndexAt(p.x);
428:   spawnWorld();
429:   if (game.bossDead && game.boss) {
430:     game.boss.alive = false;
431:     game.boss.respawn = 0;
432:     game.boss.sleeping = true;
433:   }
434:   game.cam.x = p.x;
435:   game.cam.y = p.y;
436:   game.cam.zoom = 1.02 - game.stage * 0.025;
437:   clampCamera(true);
438:   game.state = 'playing';
439:   game.hintCd = 0;
440: }
