477: function updatePlaying(dt) {
478:   const slow = game.slowmo > 0 ? 0.38 : 1;
479:   const sdt = dt * slow;
480:   game.time += sdt;
481:   game.playTime += dt;
482:   game.slowmo = Math.max(0, game.slowmo - dt);
483: 
484:   updatePlayer(sdt);
485:   updateFlowers(sdt);
486:   for (const c of game.mobs) updateMob(c, sdt);
487:   resolveHazards(sdt);
488:   updateCombat(sdt);
489:   updateParticles(sdt);
490:   updateTexts(sdt);
491:   updateMotes(sdt);
492:   updateCamera(dt);
493:   updateTimers(dt);
494:   sound.update(dt, ZONES[game.zoneIndex].id, game.state === 'playing');
495: 
496:   if (game.state !== 'playing') return;
497:   if (game.winTimer > 0) {
498:     game.winTimer -= dt;
499:     if (game.winTimer <= 0) showWin();
500:   }
501: }
502: 
503: function updatePlayer(dt) {
504:   const p = game.player;
505:   const st = STAGES[game.stage];
506:   p.attackCd -= dt;
507:   p.hurtT = Math.max(0, p.hurtT - dt);
508:   p.dashT = Math.max(0, p.dashT - dt);
509:   p.dashCd = Math.max(0, p.dashCd - dt);
510:   p.biteT = Math.max(0, p.biteT - dt);
511:   game.toughCd = Math.max(0, game.toughCd - dt);
512:   game.flowerCd = Math.max(0, game.flowerCd - dt);
513: 
514:   const inp = inputVector();
515:   if (dashQueued) {
516:     dashQueued = false;
517:     if (st.dash && p.dashCd <= 0) {
518:       // dash toward the stick/key direction, or straight ahead when standing still
519:       let dx = inp.x, dy = inp.y;
520:       if (inp.mag <= 0.12) {
521:         dx = Math.cos(p.angle);
522:         dy = Math.sin(p.angle);
523:       }
524:       const l = Math.hypot(dx, dy) || 1;
525:       p.dashVX = (dx / l) * st.speed * 2.8;
526:       p.dashVY = (dy / l) * st.speed * 2.8;
527:       p.dashT = 0.17;
528:       p.dashCd = 0.55;
529:       p.angle = Math.atan2(dy, dx);
530:       sound.dash();
531:       for (let i = 0; i < 7; i++) {
532:         burst(p.x - dx * 10, p.y - dy * 10, '#c9c6a4', 1, {
533:           speed: 40, life: 0.5, size: 2.4, type: 'dust',
534:         });
535:       }
536:       game.shake = Math.max(game.shake, 1.5);
537:     }
538:   }
539: 
540:   let speed = st.speed;
541:   const pathDist = Math.abs(p.y - pathY(p.x));
542:   if (game.zoneIndex >= 2 && pathDist > 300) speed *= 0.84;
543:   if (game.drinking) speed *= 0.94;
544: 
545:   if (p.dashT > 0) {
546:     p.vx = p.dashVX;
547:     p.vy = p.dashVY;
548:   } else {
549:     const targetVX = inp.x * speed * inp.mag;
550:     const targetVY = inp.y * speed * inp.mag;
551:     const k = 1 - Math.exp(-dt * (inp.mag > 0 ? 10 : 7));
552:     p.vx = lerp(p.vx, targetVX, k);
553:     p.vy = lerp(p.vy, targetVY, k);
554:   }
555: 
556:   p.x += p.vx * dt;
557:   p.y += p.vy * dt;
558:   p.x = clamp(p.x, 26, WORLD_W - 26);
559:   p.y = clamp(p.y, 52, WORLD_H - 52);
560: 
561:   // zone gates
562:   game.blocked = false;
563:   for (const b of BARRIERS) {
564:     if (game.stage < b.require) {
565:       if (p.x > b.x - 30) {
566:         p.x = b.x - 30;
567:         p.vx = Math.min(0, p.vx);
568:       }
569:       // latch the hint while the player is pressed against the thicket
570:       if (p.x >= b.x - 36) game.blocked = true;
571:     }
572:   }
573: 
574:   const sp = Math.hypot(p.vx, p.vy);
575:   if (sp > 20) {
576:     p.angle = lerpAngle(p.angle, Math.atan2(p.vy, p.vx), 1 - Math.exp(-dt * 12));
577:     p.walk += dt * (5 + sp * 0.07);
578:   } else {
579:     p.walk += dt * 1.1;
580:   }
581: 
582:   // water
583:   game.drinking = false;
584:   for (const pd of game.puddles) {
585:     pd.drinking = false;
586:     const ex = (p.x - pd.x) / pd.rx;
587:     const ey = (p.y - pd.y) / pd.ry;
588:     if (ex * ex + ey * ey < 1 && p.thirst < 99.99) {
589:       pd.drinking = true;
590:       game.drinking = true;
591:       p.thirst = Math.min(100, p.thirst + 52 * dt);
592:       game.splashCd -= dt;
593:       if (game.splashCd <= 0) {
594:         game.splashCd = 0.34;
595:         burst(p.x, p.y + 2, '#cfe3d8', 3, { speed: 22, life: 0.6, size: 1.8, type: 'drop', gravity: 20 });
596:         if (Math.random() > 0.5) sound.drink();
597:       }
598:     }
599:   }
600: 
601:   // tiny bites of nectar
602:   for (const f of game.flowers) {
603:     if (f.nectar <= 0) continue;
604:     if (dist2(p.x, p.y, f.x, f.y) < (p.r + f.r + 7) ** 2 && game.flowerCd <= 0) {
605:       f.nectar = 0;
606:       f.respawn = between(Math.random, FLOWER_RESPAWN[0], FLOWER_RESPAWN[1]);
607:       p.hunger = Math.min(100, p.hunger + 4);
608:       p.thirst = Math.min(100, p.thirst + 6);
609:       game.biomass += 1;
610:       game.flowerCd = 0.3;
611:       addText(f.x, f.y - 12, '+nectar', '#6d6a3f', 12);
612:       burst(f.x, f.y, f.heart, 8, { speed: 55, life: 0.8, size: 2.2, type: 'dot', gravity: 10 });
613:     }
614:   }
615: 
616:   // vitals
617:   p.hunger = clamp(p.hunger - st.hungerDrain * dt, 0, 100);
618:   p.thirst = clamp(p.thirst - st.thirstDrain * dt, 0, 100);
619:   if (p.hunger <= 0) p.hp -= 1.5 * dt;
620:   if (p.thirst <= 0) p.hp -= 2.2 * dt;
621:   if (p.hunger > 35 && p.thirst > 35) p.hp = Math.min(p.maxHp, p.hp + 1.0 * dt);
622:   p.hp = Math.min(p.hp, p.maxHp);
623:   if (p.hp <= 0 && game.state === 'playing') die();
624: 
625:   // zone change
626:   const zi = zoneIndexAt(p.x);
627:   if (zi !== game.zoneIndex) {
628:     game.zoneIndex = zi;
629:     seedMotes();
630:     enterZone(ZONES[zi]);
631:     sound.setZone(ZONES[zi].id);
632:     if (zi === 3 && game.stage >= 4 && !game.bossDead && !game.bossIntro) {
633:       game.bossIntro = true;
634:       flash('Something enormous is breathing in the roots.', 4200);
635:     }
636:   }
637: }
