639: function updateFlowers(dt) {
640:   for (const f of game.flowers) {
641:     if (f.nectar <= 0) {
642:       f.respawn -= dt;
643:       if (f.respawn <= 0) {
644:         f.nectar = 1;
645:         burst(f.x, f.y, f.heart, 5, { speed: 22, life: 1.2, size: 1.4, type: 'dot' });
646:       }
647:     }
648:   }
