726: function updateBoss(c, dt) {
727:   if (!c.alive) return;
728:   const p = game.player;
729:   const dx = p.x - c.x, dy = p.y - c.y;
730:   const d = Math.hypot(dx, dy) || 1;
731:   c.attackCd = Math.max(0, c.attackCd - dt);
732: 
733:   if (c.sleeping) {
734:     if (game.stage >= 4 && d < 620) {
735:       c.sleeping = false;
736:       c.waking = 1.3;
737:       c.aggro = true;
738:       c.state = 'idle';
739:       game.bossEngaged = true;
740:       game.shake = 9;
741:       sound.boss();
742:       flash('The Mantis Queen unfolds from the roots.', 4400);
743:       burst(c.x, c.y, '#d9c98d', 18, { speed: 120, life: 1.4, size: 2.5, type: 'dot' });
744:     } else {
745:       c.walk += dt * 0.4;
746:       return;
747:     }
748:   }
749: 
750:   if (c.waking > 0) {
751:     c.waking -= dt;
752:     c.vx *= Math.exp(-dt * 6);
753:     c.vy *= Math.exp(-dt * 6);
754:     c.x += c.vx * dt;
755:     c.y += c.vy * dt;
756:     return;
757:   }
758: 
759:   if (d > 1080) {
760:     c.aggro = false;
761:     game.bossEngaged = false;
762:     const hdx = c.homeX - c.x, hdy = c.homeY - c.y;
763:     const hd = Math.hypot(hdx, hdy) || 1;
764:     c.vx = lerp(c.vx, hdx / hd * 95, 1 - Math.exp(-dt * 3));
765:     c.vy = lerp(c.vy, hdy / hd * 95, 1 - Math.exp(-dt * 3));
766:     c.x += c.vx * dt;
767:     c.y += c.vy * dt;
768:     c.angle = lerpAngle(c.angle, Math.atan2(hdy, hdx), 1 - Math.exp(-dt * 6));
769:     c.walk += dt * 2;
770:     return;
771:   }
772: 
773:   c.aggro = true;
774:   game.bossEngaged = true;
775:   c.lungeCd -= dt;
776: 
777:   if (c.state === 'idle') {
778:     const weave = Math.sin(game.time * 1.7 + c.seed) * 0.6;
779:     let ax = dx / d - (dy / d) * weave;
780:     let ay = dy / d + (dx / d) * weave;
781:     const al = Math.hypot(ax, ay) || 1;
782:     c.vx = lerp(c.vx, (ax / al) * 152, 1 - Math.exp(-dt * 3.2));
783:     c.vy = lerp(c.vy, (ay / al) * 152, 1 - Math.exp(-dt * 3.2));
784:     if (d < 370 && c.lungeCd <= 0) {
785:       c.state = 'telegraph';
786:       c.tele = 0.62;
787:       c.vx *= 0.15;
788:       c.vy *= 0.15;
789:     }
790:   } else if (c.state === 'telegraph') {
791:     c.tele -= dt;
792:     c.vx *= Math.exp(-dt * 8);
793:     c.vy *= Math.exp(-dt * 8);
794:     if (c.tele <= 0) {
795:       c.state = 'lunge';
796:       c.lungeT = 0.37;
797:       c.lungeVX = (dx / d) * 660;
798:       c.lungeVY = (dy / d) * 660;
799:       game.shake = 7;
800:       sound.boss();
801:     }
802:   } else if (c.state === 'lunge') {
803:     c.lungeT -= dt;
804:     c.vx = c.lungeVX;
805:     c.vy = c.lungeVY;
806:     if (Math.random() > 0.7) {
807:       burst(c.x - c.vx * 0.02, c.y - c.vy * 0.02, '#c8bd92', 1, { speed: 20, life: 0.5, size: 2.4, type: 'dust' });
808:     }
809:     if (c.lungeT <= 0) {
810:       c.state = 'recover';
811:       c.recoverT = 0.85;
812:       c.lungeCd = 2.5 + Math.random() * 0.9;
813:     }
814:   } else {
815:     c.recoverT -= dt;
816:     c.vx *= Math.exp(-dt * 5);
817:     c.vy *= Math.exp(-dt * 5);
818:     if (c.recoverT <= 0) c.state = 'idle';
819:   }
820: 
821:   c.x += c.vx * dt;
822:   c.y += c.vy * dt;
823:   c.x = clamp(c.x, 5480, WORLD_W - 40);
824:   c.y = clamp(c.y, 80, WORLD_H - 80);
825: 
826:   const face = c.state === 'lunge' ? Math.atan2(c.vy, c.vx) : Math.atan2(dy, dx);
827:   c.angle = lerpAngle(c.angle, face, 1 - Math.exp(-dt * 7));
828:   c.walk += dt * (1.2 + Math.hypot(c.vx, c.vy) * 0.012);
829: }
