837:   c.x = pt.x; c.y = pt.y;
838:   c.homeX = pt.x; c.homeY = pt.y;
839:   c.vx = 0; c.vy = 0; c.kvx = 0; c.kvy = 0;
840:   c.hp = c.def.hp;
841:   c.alive = true;
842:   c.aggro = false;
