851: function updateCombat(dt) {
852:   const p = game.player;
853:   if (p.attackCd > 0) return;
854:   let target = null;
855:   let best = Infinity;
856:   for (const c of game.mobs) {
857:     if (!c.alive || c.sleeping) continue;
858:     const reach = p.r + c.r + (c.boss ? 16 : 7);
859:     const d2 = dist2(p.x, p.y, c.x, c.y);
860:     if (d2 < reach * reach && d2 < best) { best = d2; target = c; }
861:   }
862:   if (!target) return;
863: 
864:   const edible = game.stage >= target.def.tier;
865:   if (!edible) {
866:     p.attackCd = 0.55;
867:     if (game.toughCd <= 0) {
868:       game.toughCd = 2.0;
869:       addText(target.x, target.y - target.r - 8, 'too tough', '#796a50', 13);
870:     }
871:     return;
872:   }
873: 
874:   p.attackCd = STAGES[game.stage].cadence;
875:   p.biteT = 0.16;
876:   const dmg = STAGES[game.stage].bite;
877:   target.hp -= dmg;
878:   const nx = (target.x - p.x) / (dist(p.x, p.y, target.x, target.y) || 1);
879:   const ny = (target.y - p.y) / (dist(p.x, p.y, target.x, target.y) || 1);
880:   target.kvx += nx * (target.boss ? 60 : 170);
881:   target.kvy += ny * (target.boss ? 60 : 170);
882:   target.hurtT = 0.15;
883:   if (target.boss && target.sleeping) wakeBoss(target);
884: 
885:   sound.bite();
886:   game.shake = Math.max(game.shake, target.boss ? 3 : 1.2);
887:   burst((p.x + target.x) / 2, (p.y + target.y) / 2, target.def.color, 5, {
888:     speed: 90, life: 0.4, size: 2.4, type: 'spark',
889:   });
890:   if (target.boss) addText(target.x, target.y - target.r - 12, `-${dmg}`, '#8f3f3a', 15);
891: 
892:   if (target.hp <= 0) killMob(target);
893: }
