905:     burst(c.x, c.y, '#d9c98d', 45, { speed: 180, life: 2.2, size: 3, type: 'spark' });
906:     burst(c.x, c.y, '#7d9b62', 30, { speed: 90, life: 2.6, size: 5, type: 'dot', gravity: -6 });
907:     addText(c.x, c.y - 50, 'the queen folds', '#4c5d3e', 20);
