918:   addText(c.x, c.y - c.r - 8, `+${c.def.biomass}`, '#6e6a3a', 16);
919:   burst(c.x, c.y, c.def.color, 10, { speed: 80, life: 0.9, size: 2.6, type: 'dot', gravity: 25 });
920:   burst(c.x, c.y, '#f0e7c8', 4, { speed: 30, life: 0.7, size: 3, type: 'ring' });
921:   sound.eat();
922:   if (game.stage < 4 && game.biomass >= MOLT_COST[game.stage] && game.nextMilestone !== game.stage) {
