938:   p.vy += Math.sin(a) * (c.boss ? 220 : 150);
939:   addText(p.x, p.y - p.r - 10, `-${Math.round(dmg)}`, '#8f3f3a', 15);
940:   burst(p.x, p.y, '#c07a62', 7, { speed: 70, life: 0.7, size: 2.4, type: 'dot' });
