987: function burst(x, y, color, n, opts = {}) {
988:   const speed = opts.speed ?? 70;
989:   const life = opts.life ?? 0.8;
990:   const size = opts.size ?? 2.4;
991:   const type = opts.type ?? 'dot';
992:   const gravity = opts.gravity ?? 0;
993:   for (let i = 0; i < n; i++) {
994:     const a = Math.random() * TAU;
995:     const s = speed * (0.3 + Math.random() * 0.9);
996:     game.particles.push({
997:       x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s,
998:       life: life * (0.6 + Math.random() * 0.7), maxLife: life,
999:       size: size * (0.5 + Math.random() * 0.8), color, type,
1000:       rot: Math.random() * TAU, vr: between(Math.random, -6, 6), gravity,
1001:     });
1002:   }
1003:   if (game.particles.length > 420) game.particles.splice(0, game.particles.length - 420);
1004: }
