1223: function drawMotesWorld(ctx, left, top, right, bottom) {
1224:   for (const m of game.motes) {
1225:     if (m.x < left - 40 || m.x > right + 40 || m.y < top - 40 || m.y > bottom + 40) continue;
1226:     const twinkle = 0.45 + 0.55 * Math.sin(game.time * 1.6 + m.phase);
1227:     if (m.kind === 'firefly') {
1228:       const a = 0.18 + twinkle * 0.5;
1229:       ctx.fillStyle = `rgba(240,226,142,${a * 0.15})`;
1230:       ctx.beginPath(); ctx.arc(m.x, m.y, m.size * 5, 0, TAU); ctx.fill();
1231:       ctx.fillStyle = `rgba(240,226,142,${a * 0.35})`;
1232:       ctx.beginPath(); ctx.arc(m.x, m.y, m.size * 2.4, 0, TAU); ctx.fill();
1233:       ctx.fillStyle = `rgba(255,248,198,${a})`;
1234:       ctx.beginPath(); ctx.arc(m.x, m.y, m.size * 0.9, 0, TAU); ctx.fill();
1235:     } else if (m.kind === 'spore') {
1236:       ctx.fillStyle = `rgba(205,220,180,${0.12 + twinkle * 0.25})`;
1237:       ctx.beginPath(); ctx.arc(m.x, m.y, m.size * 0.8, 0, TAU); ctx.fill();
1238:     } else if (m.kind === 'fluff') {
1239:       ctx.fillStyle = `rgba(250,246,228,${0.2 + twinkle * 0.25})`;
1240:       ctx.beginPath(); ctx.ellipse(m.x, m.y, m.size * 1.8, m.size, 0.5, 0, TAU); ctx.fill();
1241:     } else {
1242:       ctx.fillStyle = `rgba(250,238,186,${0.16 + twinkle * 0.28})`;
1243:       ctx.beginPath(); ctx.arc(m.x, m.y, m.size, 0, TAU); ctx.fill();
1244:     }
1245:   }
1246: }
