1248: function drawParticles(ctx) {
1249:   for (const pt of game.particles) {
1250:     const a = clamp(pt.life / pt.maxLife, 0, 1);
1251:     if (pt.type === 'ring') {
1252:       ctx.strokeStyle = hexAWithAlpha(pt.color, a * 0.5);
1253:       ctx.lineWidth = 1.1;
1254:       ctx.beginPath();
1255:       ctx.ellipse(pt.x, pt.y, pt.size, pt.size * 0.7, 0, 0, TAU);
1256:       ctx.stroke();
1257:       continue;
1258:     }
1259:     if (pt.type === 'spark') {
1260:       ctx.strokeStyle = hexAWithAlpha(pt.color, a * 0.8);
1261:       ctx.lineWidth = pt.size * 0.55;
1262:       ctx.beginPath();
1263:       ctx.moveTo(pt.x, pt.y);
1264:       ctx.lineTo(pt.x - pt.vx * 0.02, pt.y - pt.vy * 0.02);
1265:       ctx.stroke();
1266:       continue;
1267:     }
1268:     if (pt.type === 'leaf' || pt.type === 'dust') {
1269:       ctx.save();
1270:       ctx.translate(pt.x, pt.y);
1271:       ctx.rotate(pt.rot);
1272:       ctx.fillStyle = hexAWithAlpha(pt.color, a * (pt.type === 'dust' ? 0.3 : 0.55));
1273:       ctx.beginPath();
1274:       ctx.ellipse(0, 0, pt.size * 1.5, pt.size * 0.7, 0, 0, TAU);
1275:       ctx.fill();
1276:       ctx.restore();
1277:       continue;
1278:     }
1279:     ctx.fillStyle = hexAWithAlpha(pt.color, a * 0.75);
1280:     ctx.beginPath();
1281:     ctx.arc(pt.x, pt.y, pt.size, 0, TAU);
1282:     ctx.fill();
1283:   }
1284: }
1285: 
1286: function drawFloatingText(ctx) {
1287:   for (const t of game.texts) {
1288:     const a = clamp(t.life / t.maxLife, 0, 1);
1289:     ctx.save();
1290:     ctx.globalAlpha = Math.min(1, a * 1.8);
1291:     ctx.font = `italic ${t.size}px "Palatino Linotype", "DejaVu Serif", Georgia, serif`;
1292:     ctx.textAlign = 'center';
1293:     ctx.lineWidth = 3;
1294:     ctx.strokeStyle = 'rgba(248,241,224,0.75)';
1295:     ctx.strokeText(t.text, t.x, t.y);
1296:     ctx.fillStyle = t.color;
1297:     ctx.fillText(t.text, t.x, t.y);
1298:     ctx.restore();
1299:   }
1300: }
