1302: function hexAWithAlpha(hex, a) {
1303:   if (!hex || hex[0] !== '#') return hex;
1304:   const n = parseInt(hex.slice(1), 16);
1305:   return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`;
1306: }
