1308: function drawAtmosphere(c) {
1309:   const zone = ZONES[game.zoneIndex];
1310:   const w = view.w, h = view.h;
1311:   if (zone.palette === 'garden') {
1312:     const g = c.createRadialGradient(w * 0.72, h * 0.12, 0, w * 0.72, h * 0.12, Math.max(w, h) * 0.75);
1313:     g.addColorStop(0, 'rgba(255,238,178,0.16)');
1314:     g.addColorStop(0.5, 'rgba(255,238,178,0.05)');
1315:     g.addColorStop(1, 'rgba(255,238,178,0)');
1316:     c.fillStyle = g;
1317:     c.fillRect(0, 0, w, h);
1318:   } else if (zone.palette === 'meadow') {
1319:     const g = c.createLinearGradient(0, 0, 0, h);
1320:     g.addColorStop(0, 'rgba(255,228,150,0.09)');
1321:     g.addColorStop(0.6, 'rgba(255,228,150,0.02)');
1322:     g.addColorStop(1, 'rgba(210,180,110,0.05)');
1323:     c.fillStyle = g;
1324:     c.fillRect(0, 0, w, h);
1325:   } else if (zone.palette === 'edge') {
1326:     const g = c.createLinearGradient(0, 0, 0, h);
1327:     g.addColorStop(0, 'rgba(225,225,205,0.18)');
1328:     g.addColorStop(0.45, 'rgba(225,225,205,0.03)');
1329:     g.addColorStop(1, 'rgba(40,60,48,0.08)');
1330:     c.fillStyle = g;
1331:     c.fillRect(0, 0, w, h);
1332:   } else {
1333:     c.fillStyle = 'rgba(27,48,43,0.16)';
1334:     c.fillRect(0, 0, w, h);
1335:     // god rays through the canopy
1336:     c.save();
1337:     c.translate(w * 0.62, -h * 0.2);
1338:     c.rotate(0.34);
1339:     for (let i = 0; i < 4; i++) {
1340:       const x = i * Math.max(90, w * 0.09);
1341:       const bw = Math.max(26, w * 0.035);
1342:       const g = c.createLinearGradient(x, 0, x, h * 1.6);
1343:       g.addColorStop(0, 'rgba(245,238,190,0.12)');
1344:       g.addColorStop(0.45, 'rgba(245,238,190,0.05)');
1345:       g.addColorStop(1, 'rgba(245,238,190,0)');
1346:       c.fillStyle = g;
1347:       c.fillRect(x, 0, bw, h * 1.6);
1348:     }
1349:     c.restore();
1350:     const warm = c.createRadialGradient(w * 0.8, h * 0.45, 0, w * 0.8, h * 0.45, Math.min(w, h) * 0.6);
1351:     warm.addColorStop(0, 'rgba(240,224,160,0.1)');
1352:     warm.addColorStop(1, 'rgba(240,224,160,0)');
1353:     c.fillStyle = warm;
1354:     c.fillRect(0, 0, w, h);
1355:   }
1356: }
