1358: function drawVignette(c) {
1359:   const w = view.w, h = view.h;
1360:   const g = c.createRadialGradient(w / 2, h * 0.48, Math.min(w, h) * 0.28, w / 2, h * 0.5, Math.max(w, h) * 0.72);
1361:   g.addColorStop(0, 'rgba(54,56,38,0)');
1362:   g.addColorStop(0.7, 'rgba(54,56,38,0.06)');
1363:   g.addColorStop(1, 'rgba(50,52,35,0.26)');
