1365:   c.fillRect(0, 0, w, h);
1366: 
1367:   if (game.hurtFlash > 0) {
1368:     const r = c.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.2, w / 2, h / 2, Math.max(w, h) * 0.7);
1369:     r.addColorStop(0, 'rgba(150,50,40,0)');
1370:     r.addColorStop(1, `rgba(150,50,40,${game.hurtFlash * 0.22})`);
1371:     c.fillStyle = r;
1372:     c.fillRect(0, 0, w, h);
1373:   }
1374:   const p = game.player;
1375:   if (p && p.hp / p.maxHp < 0.28 && game.state === 'playing') {
1376:     const pulse = 0.5 + 0.5 * Math.sin(game.time * 5);
1377:     const r = c.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.3, w / 2, h / 2, Math.max(w, h) * 0.7);
1378:     r.addColorStop(0, 'rgba(120,40,36,0)');
1379:     r.addColorStop(1, `rgba(120,40,36,${0.08 + pulse * 0.1})`);
1380:     c.fillStyle = r;
1381:     c.fillRect(0, 0, w, h);
1382:   }
1383: }
