1392: function updateUI() {
1393:   const p = game.player;
1394:   if (!p) return;
1395:   const st = STAGES[game.stage];
1396:   const cost = game.stage < 4 ? MOLT_COST[game.stage] : 0;
1397:   const zone = ZONES[game.zoneIndex];
1398: 
1399:   setText(ui.stageName, st.name);
1400:   setText(ui.stageNumeral, `INSTAR ${st.numeral}`);
1401:   setText(ui.stageTrait, st.trait);
1402:   setText(ui.stageZone, zone.name.replace('The ', '').toUpperCase());
1403:   setText(ui.bioNum, Math.floor(game.biomass));
1404:   setText(ui.bioMax, game.stage < 4 ? `/ ${cost}` : '/ —');
1405: 
1406:   const hpPct = clamp((p.hp / p.maxHp) * 100, 0, 100);
1407:   const huPct = clamp(p.hunger, 0, 100);
1408:   const thPct = clamp(p.thirst, 0, 100);
1409:   ui.vitFill.style.width = `${hpPct}%`;
1410:   ui.hungFill.style.width = `${huPct}%`;
1411:   ui.thirstFill.style.width = `${thPct}%`;
1412:   setText(ui.vitNum, Math.ceil(p.hp));
1413:   setText(ui.hungNum, Math.ceil(p.hunger));
1414:   setText(ui.thirstNum, Math.ceil(p.thirst));
1415:   vitalRows[0]?.classList.toggle('low', hpPct < 28);
1416:   vitalRows[1]?.classList.toggle('low', huPct < 22);
1417:   vitalRows[2]?.classList.toggle('low', thPct < 22);
1418: 
1419:   if (game.stage >= 4) {
1420:     ui.moltWrap.style.display = 'none';
1421:   } else {
1422:     ui.moltWrap.style.display = 'flex';
1423:     const ready = game.biomass >= cost;
1424:     ui.moltWrap.classList.toggle('ready', ready);
1425:     ui.moltFill.style.width = `${clamp((game.biomass / cost) * 100, 0, 100)}%`;
1426:     let note;
1427:     if (ready) note = p.thirst < 28 ? 'drink before molting' : 'ready — press E';
1428:     else note = `${Math.ceil(cost - game.biomass)} biomass to shed`;
1429:     setText(ui.moltNote, note);
1430:   }
1431: 
1432:   // skitter is a nymph trick; hide its touch button until the first molt
1433:   ui.dashBtn.style.display = game.stage >= 1 ? '' : 'none';
1434:   ui.dashBtn.classList.toggle('cooling', p.dashCd > 0.04);
1435: 
1436:   const pct = clamp((p.x / WORLD_W) * 100, 2, 98);
1437:   ui.journeyFill.style.width = `${pct}%`;
1438:   ui.journeyBug.style.left = `${pct}%`;
1439:   journeyStops.forEach((el, i) => {
1440:     el.classList.toggle('current', i === game.zoneIndex);
1441:     el.classList.toggle('done', i < game.zoneIndex);
