262:   ctx.bezierCurveTo(baseX + len * 0.12, baseY + len * 0.02, baseX + len * 0.06, baseY + len * 0.02, baseX, baseY);
263:   ctx.closePath();
264:   ctx.fillStyle = hexA(fill, 0.85);
265:   ctx.fill();
266:   ctx.strokeStyle = hexA(ink, 0.65);
267:   ctx.lineWidth = 1;
268:   ctx.stroke();
269:   // inner tooth
270:   ctx.beginPath();
271:   ctx.moveTo(baseX + len * 0.52, baseY + len * 0.1);
272:   ctx.lineTo(baseX + len * 0.46, baseY - len * 0.02);
273:   ctx.lineTo(baseX + len * 0.62, baseY + len * 0.04);
274:   ctx.closePath();
275:   ctx.fillStyle = hexA(ink, 0.55);
276:   ctx.fill();
277:   ctx.restore();
278: }
