421: export function drawCritter(ctx, c, t) {
422:   const type = c.type;
423:   const r = c.r || 8;
424:   ctx.save();
425:   ctx.translate(c.x, c.y);
426:   shadow(ctx, 2, r * 0.6, r * 1.1, r * 0.5, c.boss ? 0.28 : 0.18);
427:   const aggro = c.aggro || c.waking;
428:   if (aggro && c.def.threat > 0) {
429:     softBlob(ctx, 0, 0, r * 2.6, r * 2.2, '#b45c4c', c.boss ? 0.17 : 0.11);
430:   }
431:   ctx.rotate(c.angle || 0);
432:   const phase = c.walk || 0;
433: 
434:   switch (type) {
435:     case 'aphid': drawAphid(ctx, phase, t); break;
436:     case 'mite': drawMite(ctx, phase); break;
437:     case 'fly': drawFly(ctx, phase, t, aggro); break;
438:     case 'caterpillar': drawCaterpillar(ctx, phase); break;
439:     case 'moth': drawMoth(ctx, phase, t); break;
440:     case 'spider': drawSpider(ctx, phase, aggro); break;
441:     case 'wasp': drawWasp(ctx, phase, t, aggro); break;
442:     case 'centipede': drawCentipede(ctx, phase); break;
443:     case 'mantis': drawMantis(ctx, phase, t, c); break;
444:     default: break;
445:   }
446:   ctx.restore();
447: }
