449: function drawAphid(ctx, phase, t) {
450:   const body = '#b7ca83', ink = '#4d5838', shade = '#97ad68';
451:   for (const side of [-1, 1]) {
452:     for (let i = 0; i < 3; i++) {
453:       leg(ctx, 3 - i * 3, 0, side, phase + i * 2, 0.55, shade, ink);
454:     }
455:   }
456:   // cornicles
457:   brushCurve(ctx, -4, -2, -8, -5, -9, -6, ink, 0.35, 0.9);
458:   brushCurve(ctx, -4, 2, -8, 5, -9, 6, ink, 0.35, 0.9);
459:   // pear body
460:   washEllipse(ctx, -1, 0, 6.2, 7.2, body, 0.72, 0, 2, 0.08);
461:   inkContour(ctx, -1, 0, 6.2, 7.2, ink, 0.4, 0.8, 0, 2, 0.08);
462:   softBlob(ctx, -2, -3, 4, 2.4, '#dbe5ac', 0.4);
463:   // head
464:   washEllipse(ctx, 6, 0, 3.2, 3.4, shade, 0.85, 0, 6, 0.07);
465:   eyes(ctx, 7, 0, 1.7, 0.9, '#303a28');
466:   antennae(ctx, 8.5, 0, 5, 2, phase, ink, 0.55);
467: }
