482: function drawFly(ctx, phase, t, aggro) {
483:   const ink = '#2f3733', body = '#5d6660';
484:   const flap = 0.25 + Math.abs(Math.sin(t * 26 + phase)) * 0.75;
485:   for (const side of [-1, 1]) {
486:     ctx.save();
487:     ctx.translate(-1, side * 2.6);
488:     ctx.rotate(side * (0.25 + flap * 0.5));
489:     ctx.beginPath();
490:     ctx.ellipse(-2.5, side * (2 + 3 * flap), 7.4, 2.8, side * 0.15, 0, TAU);
491:     ctx.fillStyle = `rgba(244,246,236,${0.32 + flap * 0.22})`;
492:     ctx.fill();
493:     ctx.strokeStyle = 'rgba(90,100,92,0.25)';
494:     ctx.lineWidth = 0.5;
495:     ctx.stroke();
496:     ctx.restore();
497:   }
498:   for (const side of [-1, 1]) {
499:     for (let i = 0; i < 3; i++) leg(ctx, 3 - i * 3, 0, side, phase + i * 2, 0.5, '#4b524c', ink);
500:   }
501:   washEllipse(ctx, -2, 0, 6.6, 4.6, body, 0.8, 0, 5, 0.08);
502:   inkContour(ctx, -2, 0, 6.6, 4.6, ink, 0.5, 0.8, 0, 5, 0.08);
503:   washEllipse(ctx, 4.5, 0, 3.6, 3.4, '#454e48', 0.9, 0, 7, 0.07);
504:   // red compound eyes
505:   for (const side of [-1, 1]) {
506:     softBlob(ctx, 6, side * 1.7, 2.4, 2.2, '#b4594b', 0.5);
507:     ctx.fillStyle = '#8e4138';
508:     ctx.beginPath();
509:     ctx.arc(6.2, side * 1.8, 1.4, 0, TAU);
510:     ctx.fill();
511:   }
512:   if (aggro) softBlob(ctx, 5, 0, 4, 3, '#d08a70', 0.2);
513:   // abdomen glint
514:   softBlob(ctx, -4, -1.6, 3.2, 1.4, '#aab8ad', 0.35);
515: }
