517: function drawCaterpillar(ctx, phase) {
518:   const ink = '#56603c', body = '#aebd6d', shade = '#8c9d53';
519:   for (let i = 0; i < 6; i++) {
520:     const x = -12 + i * 4.6;
521:     const y = Math.sin(phase * 1.3 + i * 0.7) * 1.1;
522:     washEllipse(ctx, x, y, 4.4, 4.6 - Math.abs(i - 2.5) * 0.2, i % 2 ? shade : body, 0.7, 0, i + 3, 0.09);
523:     inkContour(ctx, x, y, 4.4, 4.6, ink, 0.35, 0.65, 0, i + 3, 0.1);
524:     // tiny legs
525:     for (const side of [-1, 1]) {
526:       brushCurve(ctx, x, side * 3.8, x + 0.5, side * 5.1, x - 0.4, side * 6.0, ink, 0.35, 0.6);
527:     }
528:   }
529:   // face
530:   const hx = 15, hy = Math.sin(phase * 1.3 + 4) * 1.1;
531:   washEllipse(ctx, hx, hy, 4.6, 4.4, body, 0.9, 0, 9, 0.08);
532:   eyes(ctx, hx + 1.2, hy, 2, 0.95, '#39412c');
533:   antennae(ctx, hx + 2.5, hy, 5, 2.4, phase, ink, 0.55);
534:   // stripe highlight
535:   softBlob(ctx, -4, -2.4, 7, 1.8, '#dbe3a4', 0.3);
536: }
