538: function drawMoth(ctx, phase, t) {
539:   const ink = '#5e5744', wing = '#e2d8b7', wingShade = '#b9a77a';
540:   const flap = 0.15 + Math.abs(Math.sin(t * 15 + phase)) * 0.85;
541:   for (const side of [-1, 1]) {
542:     ctx.save();
543:     ctx.translate(0, side * 2.2);
544:     ctx.scale(1, side);
545:     // forewing
546:     ctx.beginPath();
547:     ctx.ellipse(-1, 7 * flap + 1.5, 9.5, 9 * flap + 1.2, -0.25, 0, TAU);
548:     ctx.fillStyle = `rgba(233,224,197,${0.55 + flap * 0.25})`;
549:     ctx.fill();
550:     ctx.strokeStyle = hexA(ink, 0.3);
551:     ctx.lineWidth = 0.7;
552:     ctx.stroke();
553:     // hindwing
554:     ctx.beginPath();
555:     ctx.ellipse(-7, 5 * flap + 1.2, 6.5, 6.4 * flap + 1, 0.2, 0, TAU);
556:     ctx.fillStyle = `rgba(213,201,170,${0.4 + flap * 0.2})`;
557:     ctx.fill();
558:     ctx.strokeStyle = hexA(ink, 0.22);
559:     ctx.stroke();
560:     // eyespot
561:     if (flap > 0.45) {
562:       ctx.fillStyle = hexA(wingShade, 0.6 * flap);
563:       ctx.beginPath();
564:       ctx.arc(-1.5, 6 * flap + 1.5, 2.4, 0, TAU);
565:       ctx.fill();
566:       ctx.fillStyle = hexA('#6e6047', 0.5 * flap);
567:       ctx.beginPath();
568:       ctx.arc(-1.5, 6 * flap + 1.5, 1.1, 0, TAU);
569:       ctx.fill();
570:     }
571:     ctx.restore();
572:   }
573:   // body
574:   washEllipse(ctx, -2, 0, 6.5, 3.4, '#c9bfa0', 0.85, 0, 3, 0.08);
575:   inkContour(ctx, -2, 0, 6.5, 3.4, ink, 0.4, 0.7, 0, 3, 0.08);
576:   washEllipse(ctx, 4, 0, 3.4, 3.2, '#b9ad8d', 0.9, 0, 6, 0.07);
577:   eyes(ctx, 5.2, 0, 1.6, 0.9, '#3d3a2e');
578:   antennae(ctx, 6.2, 0, 5.5, 3, phase, ink, 0.5);
579:   // fuzzy thorax
580:   softBlob(ctx, 1, 0, 3.5, 3, '#efe6ca', 0.35);
581: }
