583: function drawSpider(ctx, phase, aggro) {
584:   const ink = '#3c2f27', body = '#6d5847', shade = '#4f3f33';
585:   for (let side of [-1, 1]) {
586:     for (let i = 0; i < 4; i++) {
587:       const hipX = 4 - i * 2.8;
588:       const swing = Math.sin(phase + i * 1.7 + (side > 0 ? Math.PI : 0)) * 2.5;
589:       const kx = hipX + side * 0 + 5 + swing * 0.4;
590:       const ky = side * 7;
591:       const fx = hipX + 10 + swing;
592:       const fy = side * 12;
593:       ctx.beginPath();
594:       ctx.moveTo(hipX, side * 2);
595:       ctx.quadraticCurveTo(kx, ky, fx, fy);
596:       ctx.strokeStyle = hexA(ink, 0.7);
597:       ctx.lineWidth = 1.5;
598:       ctx.stroke();
599:       ctx.strokeStyle = hexA('#8c7460', 0.5);
600:       ctx.lineWidth = 0.6;
601:       ctx.stroke();
602:     }
603:   }
604:   // abdomen
605:   washEllipse(ctx, -5, 0, 8.6, 7.4, body, 0.8, 0, 4, 0.08);
606:   inkContour(ctx, -5, 0, 8.6, 7.4, ink, 0.55, 0.9, 0, 4, 0.08);
607:   softBlob(ctx, -6, -3, 5, 2.6, '#a08668', 0.3);
608:   // hourglass
609:   ctx.fillStyle = hexA('#b45c4c', 0.72);
610:   ctx.beginPath();
611:   ctx.moveTo(-8, -2.2); ctx.lineTo(-3.5, 0); ctx.lineTo(-8, 2.2); ctx.closePath();
612:   ctx.fill();
613:   ctx.beginPath();
614:   ctx.moveTo(-4.2, -1.2); ctx.lineTo(-1.4, 0); ctx.lineTo(-4.2, 1.2); ctx.closePath();
615:   ctx.fill();
616:   // cephalothorax
617:   washEllipse(ctx, 3.5, 0, 5.2, 4.8, shade, 0.85, 0, 6, 0.07);
618:   inkContour(ctx, 3.5, 0, 5.2, 4.8, ink, 0.5, 0.8, 0, 6, 0.07);
619:   // eyes
620:   ctx.fillStyle = '#241d19';
621:   for (let i = 0; i < 3; i++) {
622:     ctx.beginPath(); ctx.arc(6.6, -1.8 + i * 1.7, 0.75, 0, TAU); ctx.fill();
623:     ctx.beginPath(); ctx.arc(4.8, -2.3 + i * 1.9, 0.6, 0, TAU); ctx.fill();
624:   }
625:   if (aggro) {
626:     softBlob(ctx, 7, 0, 3, 2.4, '#d47a60', 0.4);
627:   }
628:   // fangs
629:   brushCurve(ctx, 8, -1.2, 9.5, -1.6, 10.2, -0.6, ink, 0.6, 0.9);
630:   brushCurve(ctx, 8, 1.2, 9.5, 1.6, 10.2, 0.6, ink, 0.6, 0.9);
631: }
