633: function drawWasp(ctx, phase, t, aggro) {
634:   const ink = '#322f25', yellow = '#d9b452', dark = '#3d3b2f';
635:   const flap = 0.25 + Math.abs(Math.sin(t * 30 + phase)) * 0.75;
636:   for (const side of [-1, 1]) {
637:     ctx.save();
638:     ctx.translate(-1, side * 2.4);
639:     ctx.rotate(side * (0.2 + flap * 0.45));
640:     ctx.beginPath();
641:     ctx.ellipse(-3, side * (2 + 2.6 * flap), 8, 2.4, 0, 0, TAU);
642:     ctx.fillStyle = `rgba(243,244,233,${0.3 + flap * 0.22})`;
643:     ctx.fill();
644:     ctx.strokeStyle = 'rgba(90,95,78,0.2)';
645:     ctx.lineWidth = 0.5;
646:     ctx.stroke();
647:     ctx.restore();
648:   }
649:   for (const side of [-1, 1]) {
650:     for (let i = 0; i < 3; i++) leg(ctx, 4 - i * 3.5, 0, side, phase + i * 2, 0.55, '#b99a54', ink);
651:   }
652:   // abdomen with bands
653:   washEllipse(ctx, -8, 0, 8.4, 5.2, yellow, 0.85, 0, 4, 0.07);
654:   inkContour(ctx, -8, 0, 8.4, 5.2, ink, 0.5, 0.85, 0, 4, 0.07);
655:   for (let i = 0; i < 3; i++) {
656:     ctx.save();
657:     ctx.beginPath();
658:     ctx.ellipse(-11 + i * 4.1, 0, 1.7, 4.8 - i * 0.5, 0, 0, TAU);
659:     ctx.fillStyle = hexA(dark, 0.7);
660:     ctx.fill();
661:     ctx.restore();
662:   }
663:   // stinger
664:   ctx.beginPath();
