meleeNames.forEach((name,i)=>weapons.push({id:`m${i}`,name,type:'melee',icon:meleeIcons[i],damage:19+i*1.35,rate:0.78-i*0.012,reach:68+(i%4)*5,unlock:i<5?0:({5:3,6:4,7:5,8:6,9:7,10:8,11:9,12:10,13:12,14:15}[i]),desc:['Ráfaga corta y precisa.','Un tajo rápido que busca al más cercano.','Hoja pesada, gran impacto.','Azota en arco a varios rivales.','Golpe cálido con daño aumentado.'][i%5]}));
rangedNames.forEach((name,i)=>weapons.push({id:`r${i}`,name,type:'ranged',icon:rangeIcons[i],damage:11+i*0.9,rate:0.63-i*0.008,reach:430+(i%4)*30,unlock:i<5?0:({5:3,6:4,7:5,8:6,9:7,10:8,11:9,12:10,13:11,14:12,15:13,16:14,17:15,18:17,19:18}[i]),desc:['Proyectil veloz de energía natural.','Persigue al enemigo más próximo.','Disparo perforante de largo alcance.','Estallido que salpica alrededor.','Chispa de gran potencia.'][i%5]}));
const save = loadSave();
const game = {
  mode:'title', wave:1, timeLeft:30, elapsed:0, coins:0, kills:0, runKills:0, bossKills:0,
  player:{x:0,y:0,r:16,hp:100,maxHp:100,invuln:0,walk:0}, enemies:[], shots:[], effects:[], drops:[],
  upgrades:{power:0,haste:0,stride:0,fortune:0,vitality:0,magnet:0,thorns:0,companion:0},
  owned:new Set(['m0','m1','m2','m3','m4','r0','r1','r2','r3','r4']),
  equipped:{melee:'m0',ranged:'r0'}, levels:{}, timers:{}, spawn:0, boss:null, companionAngle:0,
  tab:'upgrades', pointer:null, keys:{}, last:performance.now(), dpr:1,w:innerWidth,h:innerHeight,
  enemyId:0, coinFloat:0, sessionWave:0, notified:new Set(), touchSeen:false,
};
for(const w of weapons) game.levels[w.id]=1;
for(const id of save.unlocked||[]) if(weapons.some(w=>w.id===id)) game.owned.add(id);
for(const id of save.unlocked||[]) game.notified.add(id);
let toastTimer=0;
function loadSave(){try{return JSON.parse(localStorage.getItem(SAVE_KEY))||{}}catch(_){return {}}}
function saveProgress(){save.unlocked=[...new Set([...(save.unlocked||[]),...[...game.owned].filter(id=>!['m0','m1','m2','m3','m4','r0','r1','r2','r3','r4'].includes(id))])];save.record=Math.max(save.record||0,game.sessionWave);save.totalKills=(save.totalKills||0)+game.runKills;save.bossKills=(save.bossKills||0)+game.bossKills;try{localStorage.setItem(SAVE_KEY,JSON.stringify(save))}catch(_){}}
function resize(){game.w=innerWidth;game.h=innerHeight;game.dpr=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.round(game.w*game.dpr);canvas.height=Math.round(game.h*game.dpr);ctx.setTransform(game.dpr,0,0,game.dpr,0,0);if(game.player.x===0&&game.player.y===0){game.player.x=game.w/2;game.player.y=game.h/2}}
addEventListener('resize',resize);resize();
$('start-button').addEventListener('click',()=>newRun());$('next-wave-button').addEventListener('click',startWave);
$('pause-button').addEventListener('click',pauseGame);$('resume-button').addEventListener('click',resumeGame);$('quit-button').addEventListener('click',()=>finishRun(false,'Has abandonado la partida. El jardín seguirá aquí.'));
$('again-button').addEventListener('click',newRun);$('mobile-tip').hidden=false;
for(const tab of document.querySelectorAll('.shop-tab'))tab.addEventListener('click',()=>{game.tab=tab.dataset.tab;renderShop()});
canvas.addEventListener('pointerdown',e=>{if(game.mode!=='combat')return;if(e.pointerType==='mouse'&&e.button!==0)return;game.pointer={id:e.pointerId,x:e.clientX,y:e.clientY,dx:0,dy:0};game.touchSeen=e.pointerType!=='mouse';try{canvas.setPointerCapture(e.pointerId)}catch(_){}});
canvas.addEventListener('pointermove',e=>{if(!game.pointer||e.pointerId!==game.pointer.id)return;game.pointer.dx=e.clientX-game.pointer.x;game.pointer.dy=e.clientY-game.pointer.y;game.pointer.x=e.clientX;game.pointer.y=e.clientY});
function pointerEnd(e){if(game.pointer&&e.pointerId===game.pointer.id)game.pointer=null}canvas.addEventListener('pointerup',pointerEnd);canvas.addEventListener('pointercancel',pointerEnd);
addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();game.keys[e.key.toLowerCase()]=true;if(e.key==='Escape'){if(game.mode==='combat')pauseGame();else if(game.mode==='pause')resumeGame()}});
addEventListener('keyup',e=>game.keys[e.key.toLowerCase()]=false);
function newRun(){game.wave=1;game.timeLeft=30;game.elapsed=0;game.coins=40;game.kills=0;game.runKills=0;game.bossKills=0;game.enemies=[];game.shots=[];game.effects=[];game.drops=[];game.upgrades={power:0,haste:0,stride:0,fortune:0,vitality:0,magnet:0,thorns:0,companion:0};game.player={x:game.w/2,y:game.h/2,r:16,hp:100,maxHp:100,invuln:0,walk:0};game.sessionWave=0;game.boss=null;game.spawn=0;game.timers={};game.levels={};for(const w of weapons)game.levels[w.id]=1;game.owned=new Set(['m0','m1','m2','m3','m4','r0','r1','r2','r3','r4']);for(const id of save.unlocked||[])if(weapons.some(w=>w.id===id))game.owned.add(id);game.equipped={melee:'m0',ranged:'r0'};game.mode='shop';hideScreens();ui.titleScreen.hidden=true;ui.pause.hidden=false;ui.hud.hidden=false;ui.badges.hidden=false;ui.record.textContent=`RÉCORD: OLEADA ${save.record||0}`;openShop(true)}
function hideScreens(){ui.titleScreen.hidden=true;ui.shop.hidden=true;ui.pauseScreen.hidden=true;ui.result.hidden=true}
function openShop(first=false){game.mode='shop';game.pointer=null;ui.shop.hidden=false;ui.pause.hidden=true;ui.hud.hidden=true;ui.badges.hidden=true;ui.shopTitle.textContent=first?'Prepara tu defensa':'Bien hecho, guardián.';ui.shopKicker.textContent=first?'EQUIPAMIENTO INICIAL':'RESPIRO ENTRE OLEADAS';ui.shopSubtitle.textContent=first?'Elige tus armas y mejoras antes de entrar al jardín.':'Invierte tus monedas. La siguiente oleada será más peligrosa.';ui.next.innerHTML=first?'Comenzar oleada 1 <span>→</span>':`¡A la oleada ${game.wave}! <span>→</span>`;renderShop()}
function startWave(){hideScreens();game.mode='combat';game.elapsed=0;game.timeLeft=30;game.spawn=.6;game.boss=null;game.player.hp=Math.min(game.player.maxHp,game.player.hp+Math.max(14,game.player.maxHp*.18));ui.hud.hidden=false;ui.badges.hidden=false;ui.pause.hidden=false;ui.phase.textContent=game.wave%10===0?'OLEADA DE JEFE':'FASE DE COMBATE';ui.title.textContent=game.wave%10===0?`Jefe · ${game.wave}`:`Oleada ${game.wave}`;updateHUD();renderBadges();toast(game.wave%10===0?'Algo enorme se mueve entre las raíces…':`Oleada ${game.wave} · ¡aguanta 30 segundos!`)}
function pauseGame(){if(game.mode!=='combat')return;game.mode='pause';game.pointer=null;ui.pauseScreen.hidden=false;ui.pause.hidden=true}
function resumeGame(){if(game.mode!=='pause')return;game.mode='combat';ui.pauseScreen.hidden=true;ui.pause.hidden=false;game.last=performance.now()}
function toast(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2100)}
function fmtTime(sec){sec=Math.max(0,Math.ceil(sec));return`00:${String(sec).padStart(2,'0')}`}
function updateHUD(){ui.coins.textContent=game.coins;ui.wave.textContent=`${game.wave} / 30`;ui.timer.textContent=fmtTime(game.timeLeft);ui.progress.style.width=`${Math.max(0,Math.min(100,(1-game.timeLeft/30)*100))}%`;ui.health.style.width=`${Math.max(0,game.player.hp/game.player.maxHp*100)}%`;ui.healthText.textContent=`${Math.ceil(game.player.hp)} / ${game.player.maxHp}`;ui.bossHealth.hidden=!game.boss;if(game.boss){ui.bossName.textContent=game.boss.name;ui.bossFill.style.width=`${Math.max(0,game.boss.hp/game.boss.maxHp*100)}%`}}
function renderBadges(){ui.badges.innerHTML=['melee','ranged'].map(type=>{const w=weapon(game.equipped[type]);return `<div class="weapon-badge"><i>${w.icon}</i><span>${w.name}</span><small>IVL ${game.levels[w.id]}</small></div>`}).join('')}

