function weapon(id){return weapons.find(w=>w.id===id)||weapons[0]}
function priceUpgrade(def){return Math.round(def.base*Math.pow(1.48,game.upgrades[def.id]))}
function evoPrice(w){return Math.round(42*Math.pow(1.68,game.levels[w.id]-1))}
function requirement(w){const n=w.type==='melee'?Number(w.id.slice(1)):Number(w.id.slice(1));const wave=w.unlock||0;const kills=Math.max(5,Math.round(wave*2.1));const boss=wave>=10&&n%4===0?Math.floor(wave/10):0;return{wave,kills,boss}}
function unlockText(w){const r=requirement(w);return r.boss?`Llega a oleada ${r.wave} y derrota ${r.boss} jefe${r.boss>1?'s':''}`:`Llega a oleada ${r.wave} y derrota ${r.kills} enemigos`}
function canUnlock(w){const r=requirement(w);return game.sessionWave>=r.wave&&game.runKills>=r.kills&&game.bossKills>=r.boss}
function checkUnlocks(){let newly=[];for(const w of weapons){if(w.unlock>0&&!save.unlocked?.includes(w.id)&&!game.owned.has(w.id)&&canUnlock(w)){save.unlocked=[...(save.unlocked||[]),w.id];newly.push(w)}}if(newly.length){newly.forEach(w=>game.notified.add(w.id));try{localStorage.setItem(SAVE_KEY,JSON.stringify({...save,record:Math.max(save.record||0,game.sessionWave)}))}catch(_){}toast(`¡Logro! ${newly[0].name} ya está disponible`);if(game.mode==='shop')renderShop()}}
function renderShop(){ui.shopCoins.textContent=game.coins;ui.unlockCount.textContent=String(weapons.filter(w=>w.unlock>0&&(save.unlocked||[]).includes(w.id)).length);document.querySelectorAll('.shop-tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===game.tab));if(game.tab==='upgrades')renderUpgrades();else if(game.tab==='weapons')renderWeapons();else renderAchievements();ui.equipped.innerHTML=`EQUIPADO <b>${weapon(game.equipped.melee).icon} ${weapon(game.equipped.melee).name}</b> · <b>${weapon(game.equipped.ranged).icon} ${weapon(game.equipped.ranged).name}</b>`}
function renderUpgrades(){ui.content.innerHTML='<p class="section-label">MEJORAS DE PARTIDA · CADA NIVEL APLICA DE INMEDIATO</p><div class="item-grid">'+upgradeDefs.map(d=>{const level=game.upgrades[d.id],cost=priceUpgrade(d),max=level>=d.max;return `<article class="shop-item"><div class="item-icon">${d.icon}</div><div class="item-info"><strong>${names[d.id]}</strong><p>${descriptions[d.id]}</p><small>NIVEL ${level}/${d.max}</small></div><button class="item-action" data-upgrade="${d.id}" ${max||game.coins<cost?'disabled':''}>${max?'MÁXIMO':`✿ ${cost}`}</button></article>`}).join('')+'</div>';
ui.content.querySelectorAll('[data-upgrade]').forEach(btn=>btn.addEventListener('click',()=>buyUpgrade(btn.dataset.upgrade)))}
function renderWeapons(){const group=(type,label)=>`<section class="weapon-group"><h3>${label}</h3><div class="weapon-list">${weapons.filter(w=>w.type===type).map(w=>weaponCard(w)).join('')}</div></section>`;ui.content.innerHTML=group('melee','✦ ARMAS CUERPO A CUERPO · 15')+group('ranged','✧ ARMAS A DISTANCIA · 20');ui.content.querySelectorAll('[data-buy]').forEach(b=>b.addEventListener('click',()=>buyWeapon(b.dataset.buy)));ui.content.querySelectorAll('[data-equip]').forEach(b=>b.addEventListener('click',()=>equipWeapon(b.dataset.equip)));ui.content.querySelectorAll('[data-evolve]').forEach(b=>b.addEventListener('click',()=>evolveWeapon(b.dataset.evolve)))}
function weaponCard(w){const owned=game.owned.has(w.id),unlocked=w.unlock===0||(save.unlocked||[]).includes(w.id),equipped=game.equipped[w.type]===w.id,level=game.levels[w.id]||1,cost=Math.round((w.type==='melee'?48:54)+Number(w.id.slice(1))*4),eCost=evoPrice(w);let action='';if(!unlocked)action=`<button class="item-action" disabled>LOGRO</button>`;else if(!owned)action=`<button class="item-action" data-buy="${w.id}" ${game.coins<cost?'disabled':''}>✿ ${cost}</button>`;else action=`<div class="weapon-actions"><button class="item-action ${equipped?'equipped':''}" data-equip="${w.id}">${equipped?'EQUIPADA':'EQUIPAR'}</button>${level<4?`<button class="item-action evolve-action" data-evolve="${w.id}" ${game.coins<eCost?'disabled':''}>IVL ${level} · ✿${eCost}</button>`:'<small class="max-level">MAX IV</small>'}</div>`;return `<article class="weapon-card ${unlocked?'':'locked'}"><div class="item-icon">${w.icon}</div><div class="item-info"><strong>${w.name}</strong><p>${w.desc}</p><small>${unlocked?(owned?`EVOLUCIÓN ${level}/4`:`${w.type==='melee'?'CUERPO A CUERPO':'A DISTANCIA'} · DISPONIBLE`):unlockText(w)}</small></div>${action}</article>`}
function renderAchievements(){const rows=weapons.filter(w=>w.unlock>0).map(w=>{const ok=(save.unlocked||[]).includes(w.id),r=requirement(w);const progress=Math.min(game.sessionWave,r.wave);const kills=Math.min(game.runKills,r.kills);const boss=Math.min(game.bossKills,r.boss);return `<article class="achievement ${ok?'done':''}"><strong>${ok?'✦':'◇'} ${w.name}</strong><p>${unlockText(w)}</p><small>${ok?'DESBLOQUEADA':`OLEADA ${progress}/${r.wave} · BAJAS ${kills}/${r.kills}${r.boss?` · JEFES ${boss}/${r.boss}`:''}`}</small></article>`}).join('');ui.content.innerHTML='<p class="section-label">LOGROS DE PARTIDA · DESBLOQUEA ARMAS PARA FUTURAS PARTIDAS</p><div class="achievement-grid">'+rows+'</div>'}
function buyUpgrade(id){const d=upgradeDefs.find(x=>x.id===id),cost=priceUpgrade(d);if(!d||game.coins<cost||game.upgrades[id]>=d.max)return;game.coins-=cost;game.upgrades[id]++;if(id==='vitality'){game.player.maxHp+=18;game.player.hp=Math.min(game.player.maxHp,game.player.hp+34)}renderShop();updateHUD()}
function buyWeapon(id){const w=weapon(id),cost=Math.round((w.type==='melee'?48:54)+Number(w.id.slice(1))*4);if(!save.unlocked?.includes(id)&&w.unlock>0||game.coins<cost||game.owned.has(id))return;game.coins-=cost;game.owned.add(id);game.equipped[w.type]=id;renderShop();renderBadges();toast(`${w.name} añadida al arsenal`)}
function equipWeapon(id){const w=weapon(id);if(!game.owned.has(id))return;game.equipped[w.type]=id;renderShop();renderBadges();toast(`${w.name} equipada`)}
function evolveWeapon(id){const w=weapon(id),cost=evoPrice(w),level=game.levels[id];if(!game.owned.has(id)||level>=4||game.coins<cost)return;game.coins-=cost;game.levels[id]++;renderShop();renderBadges();toast(`${w.name} evolucionó a nivel ${game.levels[id]}`)}

