function evolveWeapon(id){const w=weapon(id),cost=evoPrice(w),level=game.levels[id];if(!game.owned.has(id)||level>=4||game.coins<cost)return;game.coins-=cost;game.levels[id]++;renderShop();renderBadges();toast(`${w.name} evolucionó a nivel ${game.levels[id]}`)}
function startBoss(){if(game.boss||game.wave%10!==0)return;const tier=game.wave/10;game.boss={x:game.w/2+(Math.random()-.5)*140,y:-55,r:38+tier*5,hp:360+tier*260,maxHp:360+tier*260,speed:30+tier*4,damage:16+tier*4,name:['','La reina de las zarzas','El ciervo de hollín','Corazón del jardín'][tier],attack:2.5,flash:0};game.effects.push({kind:'ring',x:game.w/2,y:game.h/2,r:6,max:110,time:.9,color:'#e9a16d'});toast(`¡JEFE! ${game.boss.name}`)}
function spawnEnemy(){if(game.enemies.length>28)return;const edge=Math.floor(Math.random()*4),pad=28;let x,y;if(edge===0){x=Math.random()*game.w;y=-pad}else if(edge===1){x=game.w+pad;y=Math.random()*game.h}else if(edge===2){x=Math.random()*game.w;y=game.h+pad}else{x=-pad;y=Math.random()*game.h}const rank=Math.min(5,Math.floor((game.wave-1)/5));const roll=Math.random();let kind=roll<.58?'mite':roll<.82?'beetle':roll<.94?'moth':'thorn';const stats={mite:[14,30,8,'#d7a85e'],beetle:[34,17,13,'#c67562'],moth:[21,24,7,'#ad9ed1'],thorn:[48,12,17,'#88ae62']}[kind];const hp=stats[0]*(1+game.wave*.095);game.enemies.push({id:++game.enemyId,x,y,r:stats[1]*(.77+rank*.045),hp,maxHp:hp,speed:stats[2]*(1+game.wave*.025),kind,color:stats[3],damage:8+game.wave*.62,phase:Math.random()*6,flash:0})}
function nearestTarget(x,y,range){let best=null,bestD=range*range;for(const e of game.enemies){const d=(e.x-x)**2+(e.y-y)**2;if(d<bestD){best=e;bestD=d}}if(game.boss){const d=(game.boss.x-x)**2+(game.boss.y-y)**2;if(d<bestD){best=game.boss;bestD=d}}return best}
function weaponStats(w){const level=game.levels[w.id]||1;return{damage:w.damage*Math.pow(1.34,level-1)*(1+game.upgrades.power*.22),rate:Math.max(.18,w.rate*Math.pow(.91,level-1)/(1+game.upgrades.haste*.12)),range:w.reach*(1+level*.045)}}
function autoAttack(dt){for(const type of ['melee','ranged']){const w=weapon(game.equipped[type]),stats=weaponStats(w);game.timers[type]=(game.timers[type]||0)-dt;if(game.timers[type]>0)continue;const target=nearestTarget(game.player.x,game.player.y,stats.range);if(!target)continue;game.timers[type]=stats.rate;if(type==='melee'){const angle=Math.atan2(target.y-game.player.y,target.x-game.player.x);const n=game.levels[w.id]>=3?2:1;let hits=0;for(const e of [...game.enemies,...(game.boss?[game.boss]:[])]){if(Math.hypot(e.x-game.player.x,e.y-game.player.y)<stats.range&&(hits<n)){dealDamage(e,stats.damage,w);hits++}}game.effects.push({kind:'slash',x:game.player.x,y:game.player.y,angle,r:stats.range,time:.22,max:.22,color:game.levels[w.id]>=4?'#d7ee86':'#d4dbaa'});if(!hits)dealDamage(target,stats.damage,w)}else{const angle=Math.atan2(target.y-game.player.y,target.x-game.player.x),speed=420+game.levels[w.id]*30;game.shots.push({x:game.player.x,y:game.player.y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,r:5+game.levels[w.id],damage:stats.damage,target,life:stats.range/speed,color:game.levels[w.id]>=4?'#e6ce78':'#c8f078',weapon:w})}}}
function dealDamage(target,amount,w){if(!target)return;target.hp-=amount;target.flash=.12;game.effects.push({kind:'spark',x:target.x+(Math.random()-.5)*12,y:target.y+(Math.random()-.5)*12,r:3,time:.22,max:.22,color:w&&game.levels[w.id]>=4?'#f2db83':'#e7ecc8'});if(target.hp<=0){if(target===game.boss){game.boss=null;game.bossKills++;game.coins+=Math.round(75*(1+game.upgrades.fortune*.18));game.effects.push({kind:'ring',x:target.x,y:target.y,r:12,max:170,time:.7,color:'#e9cf73'});toast('¡Jefe derrotado! + monedas');checkUnlocks();updateHUD()}else{const i=game.enemies.indexOf(target);if(i>=0)game.enemies.splice(i,1);game.kills++;game.runKills++;const value=Math.max(2,Math.round((target.kind==='beetle'?5:target.kind==='thorn'?6:target.kind==='moth'?4:3)*(1+game.upgrades.fortune*.2)));game.drops.push({x:target.x,y:target.y,value,r:5,life:10,phase:Math.random()*5});if(game.upgrades.thorns>0&&Math.random()<.25){}if(game.runKills%4===0)checkUnlocks()}}}
function hurtPlayer(amount){const p=game.player;if(p.invuln>0)return;p.hp-=amount;p.invuln=.72;game.effects.push({kind:'ring',x:p.x,y:p.y,r:12,max:70,time:.35,color:'#f08b75'});if(game.upgrades.thorns){const attacker=nearestTarget(p.x,p.y,110);if(attacker)dealDamage(attacker,game.upgrades.thorns*7,null)}if(p.hp<=0){p.hp=0;finishRun(false,'La maleza ha cubierto el claro. Cada partida deja nuevas semillas.') }}
function update(dt){if(game.mode!=='combat')return;const p=game.player;game.elapsed+=dt;p.invuln=Math.max(0,p.invuln-dt);if(game.wave%10===0&&!game.boss&&game.timeLeft<19)startBoss();game.timeLeft-=dt;game.spawn-=dt;if(game.spawn<=0){spawnEnemy();game.spawn=Math.max(.31,1.22-game.wave*.021)*(.65+Math.random()*.7)}
let dx=0,dy=0;if(game.pointer){dx=game.pointer.dx;dy=game.pointer.dy;const len=Math.hypot(dx,dy);if(len>0){dx/=Math.max(1,len);dy/=Math.max(1,len)}}else{if(game.keys.a||game.keys.arrowleft)dx-=1;if(game.keys.d||game.keys.arrowright)dx+=1;if(game.keys.w||game.keys.arrowup)dy-=1;if(game.keys.s||game.keys.arrowdown)dy+=1;const l=Math.hypot(dx,dy)||1;dx/=l;dy/=l}const speed=205*(1+game.upgrades.stride*.1);p.x=Math.max(26,Math.min(game.w-26,p.x+dx*speed*dt));p.y=Math.max(78,Math.min(game.h-25,p.y+dy*speed*dt));if(Math.abs(dx)+Math.abs(dy)>.05)p.walk+=dt*10;
for(const e of game.enemies){const angle=Math.atan2(p.y-e.y,p.x-e.x),wiggle=Math.sin(game.elapsed*2+e.phase)*.18;e.x+=(Math.cos(angle+wiggle)*e.speed)*dt;e.y+=(Math.sin(angle+wiggle)*e.speed)*dt;e.flash=Math.max(0,e.flash-dt);if(Math.hypot(e.x-p.x,e.y-p.y)<e.r+p.r)hurtPlayer(e.damage*dt*1.6)}
if(game.boss){const b=game.boss;const a=Math.atan2(p.y-b.y,p.x-b.x);b.x+=(Math.cos(a)*b.speed+Math.sin(game.elapsed)*15)*dt;b.y+=(Math.sin(a)*b.speed+Math.cos(game.elapsed*.7)*8)*dt;b.attack-=dt;b.flash=Math.max(0,b.flash-dt);if(Math.hypot(b.x-p.x,b.y-p.y)<b.r+p.r)hurtPlayer(b.damage*dt);if(b.attack<=0){b.attack=2.2;const angle=Math.atan2(p.y-b.y,p.x-b.x);game.shots.push({x:b.x,y:b.y,vx:Math.cos(angle)*145,vy:Math.sin(angle)*145,r:8,damage:b.damage*.55,life:4,enemy:true,color:'#f29b73'})}}
autoAttack(dt);for(let i=game.shots.length-1;i>=0;i--){const s=game.shots[i];s.life-=dt;if(s.target&&!s.enemy&&(game.enemies.includes(s.target)||s.target===game.boss)){const a=Math.atan2(s.target.y-s.y,s.target.x-s.x),sp=Math.hypot(s.vx,s.vy);s.vx+=(Math.cos(a)*sp-s.vx)*Math.min(1,dt*3);s.vy+=(Math.sin(a)*sp-s.vy)*Math.min(1,dt*3)}s.x+=s.vx*dt;s.y+=s.vy*dt;let hit=false;if(s.enemy){if(Math.hypot(s.x-p.x,s.y-p.y)<p.r+s.r){hurtPlayer(s.damage);hit=true}}else{for(const e of [...game.enemies,...(game.boss?[game.boss]:[])])if(Math.hypot(s.x-e.x,s.y-e.y)<e.r+s.r){dealDamage(e,s.damage,s.weapon);hit=true;break}}if(hit||s.life<=0||s.x<-40||s.x>game.w+40||s.y<-40||s.y>game.h+40)game.shots.splice(i,1)}
const magnet=62+game.upgrades.magnet*42;for(let i=game.drops.length-1;i>=0;i--){const d=game.drops[i];d.life-=dt;const dist=Math.hypot(p.x-d.x,p.y-d.y);if(dist<magnet){const a=Math.atan2(p.y-d.y,p.x-d.x);d.x+=Math.cos(a)*(180+magnet)*dt;d.y+=Math.sin(a)*(180+magnet)*dt}if(dist<p.r+15){game.coins+=d.value;game.drops.splice(i,1);updateHUD()}else if(d.life<=0)game.drops.splice(i,1)}
for(let i=game.effects.length-1;i>=0;i--){const e=game.effects[i];e.time-=dt;if(e.kind==='ring')e.r+=(e.max-e.r)*dt*7;if(e.time<=0)game.effects.splice(i,1)}if(game.upgrades.companion){game.companionAngle+=dt*1.8;const t=nearestTarget(p.x,p.y,480);game.timers.companion=(game.timers.companion||0)-dt;if(t&&game.timers.companion<=0){game.timers.companion=.72;const a=Math.atan2(t.y-p.y,t.x-p.x);game.shots.push({x:p.x+Math.cos(game.companionAngle)*27,y:p.y+Math.sin(game.companionAngle)*27,vx:Math.cos(a)*400,vy:Math.sin(a)*400,r:5,damage:17*(1+game.upgrades.power*.15),target:t,life:1.5,color:'#9ee5ad'})}}
if(game.timeLeft<=0){game.timeLeft=0;if(game.wave%10===0&&game.boss){game.phase='boss';game.timeLeft=0}else completeWave()}updateHUD()}
function completeWave(){if(game.mode!=='combat')return;game.sessionWave=Math.max(game.sessionWave,game.wave);game.coins+=15+Math.floor(game.wave*1.6);if(game.wave%10===0&&!game.boss){game.sessionWave=game.wave;checkUnlocks()}if(game.wave>=30){finishRun(true,'Los tres guardianes han caído. El jardín vuelve a florecer.');return}game.wave++;game.enemies=[];game.shots=game.shots.filter(s=>s.enemy);game.drops=[];checkUnlocks();openShop(false)}

