function completeWave(){if(game.mode!=='combat')return;game.sessionWave=Math.max(game.sessionWave,game.wave);game.coins+=15+Math.floor(game.wave*1.6);if(game.wave>=30){finishRun(true,'Los tres guardianes han caído. El jardín vuelve a florecer.');return}game.wave++;game.enemies=[];game.shots=game.shots.filter(s=>s.enemy);game.drops=[];checkUnlocks();openShop(false)}
function finishRun(won,message){if(game.mode==='result')return;game.mode='result';game.pointer=null;game.sessionWave=Math.max(game.sessionWave,won?30:Math.max(0,game.wave-1));saveProgress();hideScreens();ui.hud.hidden=true;ui.badges.hidden=true;ui.pause.hidden=true;const kicker=$('result-kicker'),title=$('result-title'),copy=$('result-copy');kicker.textContent=won?'EL JARDÍN RECUERDA':'LA NATURALEZA RECUERDA';title.textContent=won?'¡Victoria!':'La partida termina';copy.textContent=message;$('result-stats').innerHTML=`<div><b>${game.sessionWave}</b><small>OLEADAS</small></div><div><b>${game.runKills}</b><small>BAJAS</small></div><div><b>${game.bossKills}</b><small>JEFES</small></div>`;const fresh=weapons.filter(w=>w.unlock>0&&game.notified.has(w.id));$('result-unlocks').innerHTML=fresh.length?`<div class="unlock-notice">Nuevas armas disponibles: <b>${fresh.map(w=>w.name).join(' · ')}</b></div>`:'';ui.record.textContent=`RÉCORD: OLEADA ${save.record||0}`;ui.result.hidden=false}
function renderBadges(){ui.badges.innerHTML=['melee','ranged'].map(type=>{const w=weapon(game.equipped[type]);return `<div class="weapon-badge"><i>${w.icon}</i><span>${w.name}</span><small>IVL ${game.levels[w.id]||1}</small></div>`}).join('')}
function drawBackground(){const w=game.w,h=game.h;const g=ctx.createLinearGradient(0,0,w,h);g.addColorStop(0,'#1a2a20');g.addColorStop(.55,'#14231a');g.addColorStop(1,'#101c16');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);ctx.save();ctx.globalAlpha=.16;ctx.strokeStyle='#8caa75';ctx.lineWidth=1;const spacing=58;for(let x=14;x<w;x+=spacing){ctx.beginPath();ctx.moveTo(x,75);ctx.bezierCurveTo(x+Math.sin(x)*14,h*.35,x-Math.cos(x)*20,h*.7,x+Math.sin(x*.2)*15,h);ctx.stroke()}for(let i=0;i<38;i++){const x=((i*173+37)%Math.max(1,w)),y=90+((i*239+19)%Math.max(1,h-110));ctx.fillStyle=i%3?'#8aa16b':'#c6c982';ctx.beginPath();ctx.ellipse(x,y,2+(i%3),1.4,Math.sin(i)*2,0,Math.PI*2);ctx.fill()}ctx.restore();const glow=ctx.createRadialGradient(w*.5,h*.48,5,w*.5,h*.48,Math.min(w,h)*.53);glow.addColorStop(0,'#c6e67a0b');glow.addColorStop(1,'#08120d00');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h)}
function drawEnemy(e){ctx.save();ctx.translate(e.x,e.y);ctx.rotate(Math.sin(game.elapsed*2+e.phase)*.08);if(e.flash>0){ctx.shadowBlur=22;ctx.shadowColor='#f8efd0'}ctx.fillStyle=e.flash>0?'#fff5d8':e.color;ctx.strokeStyle='#172017';ctx.lineWidth=2;ctx.beginPath();if(e.kind==='moth'){ctx.ellipse(-e.r*.35,0,e.r*.7,e.r*.52,-.55,0,Math.PI*2);ctx.ellipse(e.r*.35,0,e.r*.7,e.r*.52,.55,0,Math.PI*2);ctx.fill();ctx.fillStyle='#252b22';ctx.beginPath();ctx.arc(0,0,e.r*.38,0,Math.PI*2);ctx.fill()}else if(e.kind==='thorn'){ctx.moveTo(0,-e.r);for(let i=1;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,r=i%2?e.r*.62:e.r;ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r)}ctx.closePath();ctx.fill();ctx.stroke()}else{ctx.beginPath();ctx.ellipse(0,0,e.r,e.r*.78,0,0,Math.PI*2);ctx.fill();ctx.stroke();if(e.kind==='beetle'){ctx.strokeStyle='#f0c09988';ctx.beginPath();ctx.moveTo(0,-e.r*.68);ctx.lineTo(0,e.r*.68);ctx.stroke()}}ctx.fillStyle='#20251c';ctx.beginPath();ctx.arc(-e.r*.3,-e.r*.1,2.1,0,Math.PI*2);ctx.arc(e.r*.3,-e.r*.1,2.1,0,Math.PI*2);ctx.fill();if(e.hp<e.maxHp){ctx.fillStyle='#19251c';ctx.fillRect(-e.r,-e.r-8,e.r*2,3);ctx.fillStyle='#c8f078';ctx.fillRect(-e.r,-e.r-8,e.r*2*Math.max(0,e.hp/e.maxHp),3)}ctx.restore()}
function drawBoss(){const b=game.boss;if(!b)return;ctx.save();ctx.translate(b.x,b.y);ctx.rotate(Math.sin(game.elapsed)*.04);ctx.shadowBlur=26;ctx.shadowColor='#dc866c66';ctx.fillStyle=b.flash>0?'#fff2dc':'#8c6655';ctx.strokeStyle='#321e1c';ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,b.r,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#d3a478';ctx.beginPath();ctx.moveTo(-b.r*.72,-b.r*.5);ctx.lineTo(-b.r*1.12,-b.r*1.35);ctx.lineTo(-b.r*.25,-b.r*.8);ctx.moveTo(b.r*.72,-b.r*.5);ctx.lineTo(b.r*1.12,-b.r*1.35);ctx.lineTo(b.r*.25,-b.r*.8);ctx.fill();ctx.fillStyle='#f6d279';ctx.beginPath();ctx.arc(-b.r*.32,-b.r*.12,5,0,Math.PI*2);ctx.arc(b.r*.32,-b.r*.12,5,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#d39a76';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-b.r*.36,b.r*.38);ctx.quadraticCurveTo(0,b.r*.54,b.r*.36,b.r*.38);ctx.stroke();ctx.restore()}
function drawPlayer(){const p=game.player;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(Math.sin(p.walk)*.06);if(p.invuln>0&&Math.floor(game.elapsed*18)%2)ctx.globalAlpha=.48;const aura=ctx.createRadialGradient(0,0,5,0,0,38);aura.addColorStop(0,'#c8f07822');aura.addColorStop(1,'#c8f07800');ctx.fillStyle=aura;ctx.beginPath();ctx.arc(0,0,38,0,Math.PI*2);ctx.fill();ctx.fillStyle='#263a2a';ctx.strokeStyle='#c8e995';ctx.lineWidth=2.5;ctx.beginPath();ctx.arc(0,0,p.r,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#b8d987';ctx.beginPath();ctx.ellipse(-5,-p.r-2,5,9,-.6,0,Math.PI*2);ctx.ellipse(5,-p.r-2,5,9,.6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f3dfaa';ctx.beginPath();ctx.arc(-5,-2,2,0,Math.PI*2);ctx.arc(5,-2,2,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#d4e4b7';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,4,5,.15,Math.PI-.15);ctx.stroke();if(game.upgrades.companion){const x=Math.cos(game.companionAngle)*29,y=Math.sin(game.companionAngle)*29;ctx.fillStyle='#9ee5ad';ctx.beginPath();ctx.arc(x,y,6,0,Math.PI*2);ctx.fill()}ctx.restore()}
function draw(){ctx.clearRect(0,0,game.w,game.h);drawBackground();for(const d of game.drops){ctx.save();ctx.translate(d.x,d.y);ctx.rotate(game.elapsed*2+d.phase);ctx.fillStyle='#e5c76d';ctx.shadowBlur=12;ctx.shadowColor='#e5c76d88';ctx.beginPath();ctx.moveTo(0,-7);ctx.quadraticCurveTo(9,-2,0,7);ctx.quadraticCurveTo(-9,2,0,-7);ctx.fill();ctx.restore()}for(const e of game.effects){const alpha=Math.max(0,e.time/e.max);ctx.save();ctx.globalAlpha=alpha;if(e.kind==='spark'){ctx.fillStyle=e.color;ctx.beginPath();ctx.arc(e.x,e.y,e.r*(1+(1-alpha)),0,Math.PI*2);ctx.fill()}else if(e.kind==='ring'){ctx.strokeStyle=e.color;ctx.lineWidth=3*alpha;ctx.beginPath();ctx.arc(e.x,e.y,e.r,0,Math.PI*2);ctx.stroke()}else if(e.kind==='slash'){ctx.translate(e.x,e.y);ctx.rotate(e.angle);ctx.strokeStyle=e.color;ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,e.r*.78,-.75,.75);ctx.stroke()}ctx.restore()}for(const s of game.shots){ctx.save();ctx.fillStyle=s.color||'#f29b73';ctx.shadowBlur=12;ctx.shadowColor=s.color||'#f29b73';ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);ctx.fill();ctx.restore()}for(const e of game.enemies)drawEnemy(e);drawBoss();drawPlayer()}
function frame(now){const dt=Math.min(.04,Math.max(0,(now-game.last)/1000));game.last=now;update(dt);draw();requestAnimationFrame(frame)}
ui.record.textContent=`RÉCORD: OLEADA ${save.record||0}`;requestAnimationFrame(frame);
})();

